#ifndef BENCH_H
#define BENCH_H

/*
 * In-process driver for the memcached storage engine: replays a YCSB-style
 * READ/UPDATE operation array generated by ycsb.h against the item/assoc/slabs
 * core from bench_thread_count pthreads that call the thread-safe item API in
 * thread.c directly through stub connections, so no sockets, protocol
 * parsing, or event loops are on the measured path. The engine's event-loop
 * machinery is stubbed out by libevent_shim/, leaving POSIX pthreads as the
 * only synchronization interface. Every record key is rendered and every
 * record is loaded before the timed replay; workload generation, key
 * rendering, and loading stay untimed, leaving the measured path free of
 * stdio and formatting calls.
 */

int bench_run(void);

#endif /* BENCH_H */
